<!DOCTYPE html><html lang="{{ str_replace('_', '-', app()->getLocale()) }}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Diabetes Quiz · DiaCare</title><x-theme-script /><link rel="preconnect" href="https://fonts.bunny.net"><link href="https://fonts.bunny.net/css?family=instrument-sans:400,500,600,700,800&display=swap" rel="stylesheet" />@vite(['resources/css/app.css','resources/js/app.js'])</head><body class="landing-page"><header class="landing-nav"><a href="{{ route('welcome') }}" class="landing-brand"><span class="brand-mark brand-logo"><svg viewBox="0 0 36 36"><path d="M18 3.5 29 8v8.5c0 7.2-4.7 12.9-11 16-6.3-3.1-11-8.8-11-16V8l11-4.5Z"/><path d="m11.5 18 4 4 9-9"/></svg></span><span>DiaCare</span></a><nav><a href="{{ route('welcome') }}">Home</a><a href="{{ route('welcome') }}#about">About</a><a href="{{ route('assistant') }}">AI Chatbot</a><a href="{{ route('knowledge') }}">Knowledge Sharing</a><a class="active" href="{{ route('quiz') }}">Quiz</a><x-theme-toggle /><a class="landing-link" href="{{ route('login') }}">Login</a><a class="landing-cta" href="{{ route('register') }}">Sign up</a></nav></header><main class="public-content" x-data="diabetesQuiz()"><section class="public-hero quiz-hero"><span class="landing-kicker">Learn by playing</span><h1>Diabetes knowledge<br><em>quiz.</em></h1><p>Each refresh creates a new 10-question session. Both the questions and answer choices are shuffled from a diabetes-only question bank.</p></section><section class="quiz-card" x-show="!finished"><div class="quiz-top"><span>Question <b x-text="index + 1"></b> of <b x-text="questions.length"></b></span><span>Score: <b x-text="score"></b></span></div><div class="quiz-progress"><span :style="`width:${((index + 1) / questions.length) * 100}%`"></span></div><h2 x-text="questions[index].question"></h2><div class="quiz-options"><template x-for="(option, optionIndex) in questions[index].options" :key="option"><button type="button" :class="{ chosen: selected === optionIndex, correct: answered && optionIndex === questions[index].answer, wrong: answered && selected === optionIndex && selected !== questions[index].answer }" @click="choose(optionIndex)" x-text="option"></button></template></div><div class="quiz-feedback" x-show="answered" x-cloak><strong x-text="selected === questions[index].answer ? 'Correct!' : 'Not quite.'"></strong><p x-text="questions[index].explanation"></p></div><div class="quiz-actions"><button type="button" class="secondary-button" x-show="index > 0" @click="back()">← Back</button><button type="button" class="secondary-button" @click="quit()">Quit quiz</button><button type="button" class="primary-button" x-show="!answered" @click="check()" :disabled="selected === null">Check answer</button><button type="button" class="primary-button" x-show="answered" @click="next()" x-text="index === questions.length - 1 ? 'See result' : 'Next question'"></button></div></section><section class="quiz-result" x-show="finished" x-cloak><span class="landing-kicker" x-text="quitRequested ? 'Quiz ended' : 'Quiz complete'"></span><h2 x-show="!quitRequested">You scored <em x-text="score"></em> out of <em x-text="questions.length"></em>.</h2><h2 x-show="quitRequested">You left the quiz early.</h2><p x-text="scoreMessage"></p><button type="button" class="landing-cta landing-cta-large" @click="restart()">Shuffle a new quiz <span>↻</span></button></section><p class="quiz-note">This quiz is for general learning only and is not a medical test.</p></main><footer class="landing-footer"><div class="landing-brand"><span class="brand-mark brand-logo"><svg viewBox="0 0 36 36"><path d="M18 3.5 29 8v8.5c0 7.2-4.7 12.9-11 16-6.3-3.1-11-8.8-11-16V8l11-4.5Z"/><path d="m11.5 18 4 4 9-9"/></svg></span><span>DiaCare</span></div><span>© {{ date('Y') }} DiaCare</span></footer><script>window.diabetesQuiz=()=>({index:0,score:0,selected:null,answered:false,finished:false,scoreMessage:'',questions:[],bank:[
{question:'What does insulin help the body do?',options:['Move glucose into cells for energy','Create oxygen in the lungs','Measure blood pressure','Digest water'],answer:0,explanation:'Insulin helps glucose move from the blood into cells so it can be used for energy.'},
{question:'Which can affect a glucose reading?',options:['Meals, activity, stress, and illness','Only height','Eye colour','Shoe size'],answer:0,explanation:'Many factors can affect readings, including meals, activity, stress, illness, sleep, and medication.'},
{question:'What is type 1 diabetes?',options:['An autoimmune condition where insulin-producing cells are damaged','A temporary reaction to one meal','A condition caused by drinking water','A type of blood pressure'],answer:0,explanation:'In type 1 diabetes, the immune system attacks insulin-producing beta cells.'},
{question:'What is type 2 diabetes commonly associated with?',options:['Insulin resistance and reduced insulin production','A broken glucose meter','Only childhood infections','Eye colour'],answer:0,explanation:'Type 2 diabetes involves insulin resistance and, over time, the body may produce less insulin.'},
{question:'What is gestational diabetes?',options:['Diabetes first recognized during pregnancy','Diabetes caused by exercise','A type of glucose meter','A medication reminder'],answer:0,explanation:'Gestational diabetes develops during pregnancy and should be discussed with the pregnancy care team.'},
{question:'Why record whether a glucose reading was before or after a meal?',options:['It helps reveal patterns','It changes the meter battery','It makes the number disappear','It replaces medical advice'],answer:0,explanation:'Context helps you and your care team understand how meals and timing relate to readings.'},
{question:'What is the safest way to change a diabetes medication dose?',options:['Ask a qualified healthcare professional','Copy a friend’s dose','Use a random online comment','Double it after a high reading'],answer:0,explanation:'Medication changes should be discussed with a qualified healthcare professional.'},
{question:'What does a meal photo AI result provide?',options:['A nutrition estimate','A medical diagnosis','A laboratory result','A prescription'],answer:0,explanation:'Photo analysis estimates nutrition from what is visible and may not be exact.'},
{question:'Why can regular activity be useful to track?',options:['It helps you notice routine patterns','It guarantees a normal reading','It replaces medication','It measures insulin directly'],answer:0,explanation:'Recording activity type and duration can help you notice how your routine connects with other records.'},
{question:'What is a glucose target range?',options:['A personal range discussed with your care team','The same number for everyone','A meal calorie count','A blood pressure prescription'],answer:0,explanation:'Targets are personal and may vary by person, situation, and care plan.'},
{question:'What should you do with a persistent or concerning reading?',options:['Discuss it with your healthcare team','Ignore every reading','Change medicine without advice','Delete the record'],answer:0,explanation:'A record of repeated or concerning readings can help your healthcare team guide you.'},
{question:'Which nutrient is a carbohydrate?',options:['Rice','Water','Salt','Vitamin D'],answer:0,explanation:'Rice is a carbohydrate-containing food. Carbohydrates are broken down into glucose.'},
{question:'Why are portion sizes relevant to meal tracking?',options:['They help make nutrition estimates more realistic','They determine your blood type','They replace glucose readings','They prevent all glucose changes'],answer:0,explanation:'Portion size affects the amount of energy and carbohydrate in a meal.'},
{question:'What is hypoglycemia generally referring to?',options:['Glucose that is lower than a person’s safe range','Any high blood pressure','A type of exercise','A meal photo'],answer:0,explanation:'Low glucose can be serious. Follow your personal care plan and seek help when appropriate.'},
{question:'What is hyperglycemia generally referring to?',options:['Glucose that is higher than a person’s target or safe range','A normal heart rate','A medication schedule','A type of food label'],answer:0,explanation:'High glucose may need attention, especially if persistent or accompanied by concerning symptoms.'},
{question:'Why should an AI health answer be checked carefully?',options:['AI can make mistakes and does not know your full medical history','AI always replaces a clinician','AI can prescribe medicine','AI measures glucose remotely'],answer:0,explanation:'AI can support education but cannot replace personalized medical assessment.'},
{question:'What is a useful reason to keep a health record?',options:['To discuss patterns and questions with your care team','To avoid all appointments','To guarantee a diagnosis','To share private data publicly'],answer:0,explanation:'A clear record can support more informed conversations with your healthcare team.'},
{question:'What can sleep and stress do?',options:['They may influence glucose patterns','They never affect the body','They replace insulin','They measure carbohydrates'],answer:0,explanation:'Sleep, stress, illness, and hormones can influence glucose for some people.'},
{question:'What should a person do if they have severe urgent symptoms?',options:['Seek appropriate urgent medical help','Wait for an app notification','Ask a quiz for a diagnosis','Delete their records'],answer:0,explanation:'Urgent symptoms require appropriate medical help rather than waiting for an app or chatbot.'},
{question:'What does BMI use in its basic calculation?',options:['Height and weight','Glucose and medication','Age and eye colour','Meal photo and steps'],answer:0,explanation:'BMI is a screening calculation based on height and weight; it is not a complete health diagnosis.'}],init(){this.restart()},shuffle(a){return [...a].sort(()=>Math.random()-.5)},restart(){let expanded=[];let wording=['Which statement is correct about','What is an important diabetes fact about','Which answer best explains','What should a learner know about','Which is true when learning about'];this.bank.forEach((q,baseIndex)=>{for(let variant=0;variant<25;variant++){expanded.push({...q,id:baseIndex+'-'+variant,question:q.question})}});let previous=localStorage.getItem('diacare-last-quiz')||'';let round;do{round=this.shuffle(expanded).slice(0,10)}while(previous&&round.map(q=>q.id).sort().join('|')===previous);this.questions=round.map(q=>{let pairs=this.shuffle(q.options.map((text,i)=>({text,correct:i===q.answer})));return {...q,options:pairs.map(p=>p.text),answer:pairs.findIndex(p=>p.correct)}});localStorage.setItem('diacare-last-quiz',this.questions.map(q=>q.id).sort().join('|'));this.index=0;this.score=0;this.answers=[];this.selected=null;this.answered=false;this.finished=false;this.quitRequested=false},choose(i){if(!this.answered)this.selected=i},check(){if(this.selected===null)return;this.answered=true;this.answers[this.index]=this.selected},next(){if(!this.answered)return;if(this.index===this.questions.length-1){this.score=this.answers.filter((answer,i)=>answer===this.questions[i].answer).length;this.finished=true;this.scoreMessage=this.score===10?'Excellent work!':this.score>=7?'Great job!':this.score>=5?'Good start—review the Knowledge Sharing page for more.':'Keep learning and try a new shuffled quiz.';return}this.index++;this.selected=this.answers[this.index]??null;this.answered=this.answers[this.index]!==undefined},back(){if(this.index>0){this.index--;this.selected=this.answers[this.index]??null;this.answered=this.answers[this.index]!==undefined}},quit(){this.score=this.answers.filter((answer,i)=>answer===this.questions[i].answer).length;this.scoreMessage='You answered '+this.answers.filter(answer=>answer!==undefined).length+' of 10 questions. You can start a new shuffled quiz whenever you are ready.';this.quitRequested=true;this.finished=true}});</script></body></html>
